def extract_steps(info, empty_id) -> 'list':  #799 (line in Coconut source)
    """Collect the steps leading to the empty clause, renumbered from 1."""  #800 (line in Coconut source)
    used = set()  #801 (line in Coconut source)
    stack = [empty_id,]  #802 (line in Coconut source)
    while stack:  #803 (line in Coconut source)
        cid = stack.pop()  #804 (line in Coconut source)
        if cid not in used:  #805 (line in Coconut source)
            used.add(cid)  #806 (line in Coconut source)
            stack.extend(info[cid][2])  #807 (line in Coconut source)
    renumber = _coconut.dict(((cid), (n)) for n, cid in enumerate(sorted(used), 1))  #808 (line in Coconut source)
    def make_step(cid):  #809 (line in Coconut source)
        lits, rule, parents = info[cid]  #810 (line in Coconut source)
        return ProofStep(renumber[cid], clause_formula(lits), rule, (tuple)((map)(renumber.__getitem__, parents)))  #811 (line in Coconut source)

    return (list)((map)(make_step, sorted(used)))  #812 (line in Coconut source)


# Proving:


def as_premises(givens) -> 'tuple':  #817 (line in Coconut source)
    """Convert a formula or iterable of formulas into a tuple of formulas."""  #818 (line in Coconut source)
    if wff(givens) or isinstance(givens, bool):  #819 (line in Coconut source)
        givens = (givens,)  #820 (line in Coconut source)
    return tuple((top if g is True else bot if g is False else g for g in givens))  #821 (line in Coconut source)


def prove(givens, conclusion, nonempty_universe=True, timeout=default_timeout, max_clauses=default_max_clauses, want_proof=True):  #823 (line in Coconut source)
    """Try to prove conclusion from givens (a formula or an iterable of
    formulas), returning a Proof object.

    Assumes something exists unless nonempty_universe=False. Free constants
    are assumed to refer to something, so mentioning one implies that
    something exists. Free ?variables are implicitly universally quantified.

    Function-free problems are always decided; for others, the search gives
    up with status "unknown" after timeout seconds or max_clauses clauses."""  #832 (line in Coconut source)
    premises = as_premises(givens)  #833 (line in Coconut source)
    conclusion = as_premises(conclusion)[0]  #834 (line in Coconut source)
    for formula in premises + (conclusion,):  #835 (line in Coconut source)
        if not wff(formula):  #836 (line in Coconut source)
            raise TypeError("expected a formula but got {_coconut_format_0!r}".format(_coconut_format_0=(formula)))  #837 (line in Coconut source)
    closed_premises = tuple(map(universal_closure, premises))  #838 (line in Coconut source)
    closed_conclusion = universal_closure(conclusion)  #839 (line in Coconut source)

# in a possibly empty universe, first check the empty universe itself
    everything = And(*_coconut.itertools.chain(closed_premises, (closed_conclusion,)))  #842 (line in Coconut source)
    if not nonempty_universe and admits_empty_universe(everything):  #843 (line in Coconut source)
        empty_check = Imp(And(*map(empty_value, closed_premises)), empty_value(closed_conclusion))  #844 (line in Coconut source)
        if not prop_valid(empty_check):  #845 (line in Coconut source)
            return Proof(premises, conclusion, "disproved", reason="(the premises are true but the conclusion is false in the empty universe)")  #846 (line in Coconut source)

# Skolemize and clausify the premises and the negated conclusion
    used = all_names(everything)  #849 (line in Coconut source)
    num_defs = [0,]  #850 (line in Coconut source)
    def new_definition(vs):  #851 (line in Coconut source)
        num_defs[0] += 1  #852 (line in Coconut source)
        name = definition_prefix + str(num_defs[0])  #853 (line in Coconut source)
        while name in used:  #854 (line in Coconut source)
            num_defs[0] += 1  #855 (line in Coconut source)
            name = definition_prefix + str(num_defs[0])  #856 (line in Coconut source)
        used.add(name)  #857 (line in Coconut source)
        return Pred(name, *vs)  #858 (line in Coconut source)


    original_names = set(used)  #860 (line in Coconut source)
    labeled = [(p, "premise {_coconut_format_0}".format(_coconut_format_0=(i))) for i, p in enumerate(closed_premises, 1)] + [(Not(closed_conclusion), "negated conclusion"),]  #861 (line in Coconut source)
    initial = []  #862 (line in Coconut source)
    for formula, label in labeled:  #863 (line in Coconut source)
        skolemized = skolemize_formula(formula, used)  #864 (line in Coconut source)
        initial.extend(((clause, label) for clause in clausify(skolemized, new_definition)))  #865 (line in Coconut source)
    clauses = [c for c, _ in initial]  #866 (line in Coconut source)

# look for a small countermodel; for function-free problems, a model
#  exists only if there is one no bigger than the number of constants
    consts = {t for c in clauses for lit in c for t in atom_terms(atom_of(lit)) if isinstance(t, Const)}  #870 (line in Coconut source)
    function_free = all((not isinstance(t, Func) for c in clauses for lit in c for t in atom_terms(atom_of(lit))))  #871 (line in Coconut source)
    max_size = max(len(consts), 1) if function_free else max_model_size  #875 (line in Coconut source)
    model, searched = find_model(clauses, max_size)  #876 (line in Coconut source)
    if model is not None:  #877 (line in Coconut source)
        model.hidden = {name for (name, args) in model.functions if args and name not in original_names}  #878 (line in Coconut source)
        return Proof(premises, conclusion, "disproved", countermodel=model)  #879 (line in Coconut source)
    decided = function_free and searched == max_size  #880 (line in Coconut source)
    if decided and not want_proof:  #881 (line in Coconut source)
        return Proof(premises, conclusion, "proved")  #882 (line in Coconut source)

    status, info, empty_id = saturate(initial, timeout, max_clauses)  #884 (line in Coconut source)
    if status == "unsat":  #885 (line in Coconut source)
        return Proof(premises, conclusion, "proved", steps=extract_steps(info, empty_id))  #886 (line in Coconut source)
    if decided:  #887 (line in Coconut source)
        return Proof(premises, conclusion, "proved", reason="(there are no models no bigger than the number of constants; the search for a resolution proof ran out of resources)")  #888 (line in Coconut source)
    if status == "sat":  #889 (line in Coconut source)
        return Proof(premises, conclusion, "disproved", reason="(the premises and the negated conclusion are consistent: the proof search saturated without a contradiction)")  #890 (line in Coconut source)
    return Proof(premises, conclusion, "unknown", reason="(gave up after {_coconut_format_0} clauses with no countermodel of size {_coconut_format_1} or less; the conclusion may or may not follow)".format(_coconut_format_0=(len(info)), _coconut_format_1=(searched)))  #891 (line in Coconut source)


def proves(givens, conclusion, nonempty_universe=True, timeout=default_timeout, max_clauses=default_max_clauses) -> 'bool':  #893 (line in Coconut source)
    """Determine whether givens (a formula or an iterable of formulas) prove
    conclusion. Assumes something exists unless nonempty_universe=False.

    If the search runs out of resources without deciding the question, a
    warning is issued and False is returned (use prove() to distinguish this
    case)."""  #899 (line in Coconut source)
    result = prove(givens, conclusion, nonempty_universe=nonempty_universe, timeout=timeout, max_clauses=max_clauses, want_proof=False)  #900 (line in Coconut source)
    if result.status == "unknown":  #901 (line in Coconut source)
        warnings.warn("could not decide whether {_coconut_format_0!r} holds within the resource limits; assuming it does not".format(_coconut_format_0=(result)), RuntimeWarning, stacklevel=2)  #902 (line in Coconut source)
    return result.proved  #903 (line in Coconut source)


def strict_proves(givens, conclusion, **kwargs) -> 'bool':  #905 (line in Coconut source)
    """Same as proves, but doesn't assume that something exists."""  #906 (line in Coconut source)
    return proves(givens, conclusion, nonempty_universe=False, **kwargs)  #907 (line in Coconut source)


def strict_prove(givens, conclusion, **kwargs):  #909 (line in Coconut source)
    """Same as prove, but doesn't assume that something exists."""  #910 (line in Coconut source)
    return prove(givens, conclusion, nonempty_universe=False, **kwargs)  #911 (line in Coconut source)
